/**
 * The runner-signing key: a DEDICATED Ed25519 key held by the pipeline service
 * alone (never the platform user-token key), generated by
 * deploy/bin/runner-signing-keys.sh. The current key signs; the previous one
 * (rotation overlap) is only published, so requests signed either side of a
 * rotation verify.
 *
 * Read from `RUNNER_SIGNING_KEY` (inline PKCS#8 PEM) or `RUNNER_SIGNING_KEY_FILE`,
 * and `RUNNER_SIGNING_KEY_PREVIOUS` / `RUNNER_SIGNING_KEY_PREVIOUS_FILE` — a
 * missing or empty previous file simply means "no rotation in progress".
 */

import { createPrivateKey, type KeyObject } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createLogger, errorMessage } from '@pipeline-builder/api-core';
import { RUN_REQUEST_ISS, RUN_REQUEST_TTL_MS, RUN_REQUEST_TYP, type RunClaims, type RunnerAction } from '@pipeline-builder/api-core/pipeline-runners';
import { ed25519Jwk, signEdDsaJws, type Ed25519Jwk } from './jws.js';

const logger = createLogger('runner-signing');

/** The signed request's fixed protocol fields. */
export { RUN_REQUEST_ISS, RUN_REQUEST_TYP };

/** `status` is read-only: the runner reports an execution's state (GetPipelineExecution). */
export type SignedAction = RunnerAction;

/** What one signed run request asserts (iss/iat/exp are added by the signer). */
export interface RunRequestClaimsInput {
  runnerId: string;
  requestId: string;
  action: SignedAction;
  pipelineId?: string;
  hint?: { region: string; pipelineName: string };
  executionId?: string;
  requestedBy: string;
  /** The request's own expiry: the token never outlives it. */
  expiresAt?: Date;
}

export interface RunRequestSigner {
  /** The public key set (`{ keys }`) the JWKS route serves — current first. */
  jwks(): { keys: Ed25519Jwk[] };
  /** A compact JWS for one request. */
  sign(input: RunRequestClaimsInput): string;
}

/** Build a signer over explicit keys (tests and {@link loadRunnerSigner}). */
export function createRunRequestSigner(current: KeyObject, previous: KeyObject | undefined, now: () => number = Date.now): RunRequestSigner {
  const currentJwk = ed25519Jwk(current);
  const keys = [currentJwk, ...(previous ? [ed25519Jwk(previous)] : [])].filter((k, i, all) => all.findIndex((o) => o.kid === k.kid) === i);
  return {
    jwks: () => ({ keys: keys.map((k) => ({ ...k })) }),
    sign(input) {
      const iat = Math.floor(now() / 1000);
      const cap = input.expiresAt ? Math.floor(input.expiresAt.getTime() / 1000) : Number.POSITIVE_INFINITY;
      const exp = Math.max(iat + 1, Math.min(iat + RUN_REQUEST_TTL_MS / 1000, cap));
      const claims: RunClaims = {
        iss: RUN_REQUEST_ISS,
        aud: input.runnerId,
        jti: input.requestId,
        iat,
        exp,
        action: input.action,
        ...(input.pipelineId ? { pipelineId: input.pipelineId } : {}),
        ...(input.hint ? { hint: input.hint } : {}),
        ...(input.executionId ? { executionId: input.executionId } : {}),
        requestedBy: input.requestedBy,
      };
      return signEdDsaJws({ typ: RUN_REQUEST_TYP, kid: currentJwk.kid }, claims, current);
    },
  };
}

function readPem(inline: string | undefined, file: string | undefined, read: (p: string) => string): string | undefined {
  if (inline && inline.trim()) return inline;
  if (!file || !file.trim()) return undefined;
  try {
    const pem = read(file);
    return pem.trim() ? pem : undefined;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
    throw err;
  }
}

function parseEd25519(pem: string, which: string): KeyObject {
  const key = createPrivateKey(pem);
  if (key.asymmetricKeyType !== 'ed25519') throw new Error(`${which} is not an Ed25519 key`);
  return key;
}

/**
 * The signer from the environment, or `null` when no usable key is configured
 * (runners are then unavailable). An unreadable/invalid key is logged — never
 * its content — and also yields `null`.
 */
export function loadRunnerSigner(
  env: NodeJS.ProcessEnv = process.env,
  read: (p: string) => string = (p) => readFileSync(p, 'utf8'),
  now: () => number = Date.now,
): RunRequestSigner | null {
  try {
    const current = readPem(env.RUNNER_SIGNING_KEY, env.RUNNER_SIGNING_KEY_FILE, read);
    if (!current) return null;
    const previous = readPem(env.RUNNER_SIGNING_KEY_PREVIOUS, env.RUNNER_SIGNING_KEY_PREVIOUS_FILE, read);
    return createRunRequestSigner(
      parseEd25519(current, 'RUNNER_SIGNING_KEY'),
      previous ? parseEd25519(previous, 'RUNNER_SIGNING_KEY_PREVIOUS') : undefined,
      now,
    );
  } catch (err) {
    logger.error('Runner signing key unusable; cross-account runners are unavailable', { error: errorMessage(err) });
    return null;
  }
}

/** Whether a runner signing key is configured at all (inline or file) — checked without reading it. */
export function runnerSigningKeyConfigured(env: NodeJS.ProcessEnv = process.env): boolean {
  return !!(env.RUNNER_SIGNING_KEY?.trim() || env.RUNNER_SIGNING_KEY_FILE?.trim());
}
